请对以下 case 进行三维加权评分。

=== case_id ===
Case-21-stocks-008

=== 用户原始指令 (query.txt) ===
帮我搞个基金净值数字会跳的卡片,点一下直接赎回,加个天气,跌到警戒线要弹提醒

=== TaskSpec 契约 (task.taskSpec.json) ===
{
  "userQuery": "帮我搞个基金净值数字会跳的卡片,点一下直接赎回,加个天气,跌到警戒线要弹提醒",
  "size": "2x2",
  "eventCandidates": [
    {
      "call": "clickToDeeplink",
      "args": {
        "bundleName": "",
        "abilityName": "",
        "uri": "fund://redeem"
      }
    }
  ],
  "dataModelSchema": {
    "data": {
      "fund": {
        "name": {
          "type": "string",
          "description": "基金简称或卡片展示对象名称。",
          "sampleValue": "稳健收益"
        },
        "navText": {
          "type": "string",
          "description": "基金当前单位净值展示文本，运行时更新后形成跳动数字效果。",
          "sampleValue": "1.2386"
        },
        "changeText": {
          "type": "string",
          "description": "基金净值较上一周期的涨跌幅展示文本。",
          "sampleValue": "-0.42%"
        },
        "warningText": {
          "type": "string",
          "description": "净值跌到警戒线后触发的提醒状态文案。",
          "sampleValue": "已触发提醒"
        }
      },
      "weather": {
        "current": {
          "temperatureText": {
            "type": "string",
            "description": "当前温度展示文本。",
            "sampleValue": "26°C"
          },
          "condition": {
            "type": "string",
            "description": "当前天气现象。",
            "sampleValue": "多云"
          }
        }
      }
    }
  },
  "assetCandidates": []
}

